cat > ReservationStatus.java <<'EOF'
package br.com.marealta.domain;

import java.util.Set;

public enum ReservationStatus {
    PENDING(true),
    CONFIRMED(true),
    CHECKED_IN(true),
    CHECKED_OUT(true),
    CANCELLED(false);

    private static final java.util.Map<ReservationStatus, Set<ReservationStatus>> NEXT = new java.util.EnumMap<>(
            java.util.Map.of(
                    PENDING, Set.of(),
                    CONFIRMED, Set.of(),
                    CHECKED_IN, Set.of(),
                    CHECKED_OUT, Set.of(),
                    CANCELLED, Set.of()));

    static {
        NEXT.put(PENDING, Set.of(CONFIRMED, CANCELLED));
        NEXT.put(CONFIRMED, Set.of(CHECKED_IN, CANCELLED));
        NEXT.put(CHECKED_IN, Set.of(CHECKED_OUT));
    }

    private final boolean holdsRoom;

    ReservationStatus(boolean holdsRoom) {
        this.holdsRoom = holdsRoom;
    }

    public boolean canMoveTo(ReservationStatus next) {
        return NEXT.get(this).contains(next);
    }

    /** Reservas não canceladas ocupam o quarto nas suas noites. */
    public boolean holdsRoom() {
        return holdsRoom;
    }

    /** Reserva paga: confirmada, com check-in ou com check-out. */
    public boolean isPaid() {
        return this == CONFIRMED || this == CHECKED_IN || this == CHECKED_OUT;
    }
}
